package com.productionhouse.crm.legal.rights.api;
import com.productionhouse.crm.legal.rights.dto.*;import com.productionhouse.crm.legal.rights.service.ContentRightService;import jakarta.validation.Valid;import org.springframework.data.domain.Page;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;
@RestController @RequestMapping("/api/legal/rights") public class ContentRightController{private final ContentRightService service;public ContentRightController(ContentRightService service){this.service=service;}
@GetMapping @PreAuthorize("hasAuthority('RIGHTS_READ')") public Page<ContentRightResponse> list(@RequestParam(required=false)String q,@RequestParam(required=false)String status,@RequestParam(required=false)String projectRef,@RequestParam(required=false)Long mediaId,@RequestParam(required=false)String territory,@RequestParam(required=false)String platform,@RequestParam(required=false)LocalDate expiresBefore,@RequestParam(required=false)Integer expiresWithinDays,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt")String sort,@RequestParam(defaultValue="desc")String direction){return service.list(q,status,projectRef,mediaId,territory,platform,expiresBefore,expiresWithinDays,page,size,sort,direction);}
@GetMapping("/{id}") @PreAuthorize("hasAuthority('RIGHTS_READ')") public ContentRightResponse get(@PathVariable Long id){return service.get(id);}
@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAuthority('RIGHTS_WRITE')") public ContentRightResponse create(@Valid @RequestBody ContentRightRequest request){return service.create(request);}
@PutMapping("/{id}") @PreAuthorize("hasAuthority('RIGHTS_WRITE')") public ContentRightResponse update(@PathVariable Long id,@Valid @RequestBody ContentRightRequest request){return service.update(id,request);}
@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasAuthority('RIGHTS_DELETE')") public void delete(@PathVariable Long id){service.delete(id);}}
